"""Hashing, stacks and queues, linked lists."""
from dsl import fn, linked

U = "hashing"
fn("has-duplicate-value", "Any Duplicates", U, "easy", "Seen sets", "Write `has_duplicate(items)` returning True if any value appears more than once. A set remembers what you have seen in constant time.", "def has_duplicate(items):\n    seen = set()\n    for item in items:\n        if item in seen:\n            return True\n        seen.add(item)\n    return False", [([1, 2, 1], True), ([1, 2, 3], False)], [([], ), (["a", "a"], ), ([0], )])
fn("first-repeated-value", "First Repeated Value", U, "easy", "Seen sets", "Write `first_repeat(items)` returning the first value that has already been seen when walking left to right, or None.", "def first_repeat(items):\n    seen = set()\n    for item in items:\n        if item in seen:\n            return item\n        seen.add(item)\n    return None", [([2, 1, 3, 1, 2], 1), ([1, 2], None)], [([], ), ([5, 5], )])
fn("intersection-of-two", "Common Values", U, "easy", "Seen sets", "Write `common(a, b)` returning a sorted list of the values in both lists, each once.", "def common(a, b):\n    return sorted(set(a) & set(b))", [(([1, 2, 2], [2, 3]), [2]), (([], [1]), [])], [([1, 2], [3, 4]), ([5, 5], [5, 5])])
fn("missing-number-in-range", "Missing Number", U, "easy", "Seen sets", "A list holds different numbers from 0 to n with exactly one missing. Write `missing(nums)` returning it.", "def missing(nums):\n    present = set(nums)\n    for value in range(len(nums) + 1):\n        if value not in present:\n            return value", [([3, 0, 1], 2), ([0], 1)], [([1], ), ([], ), ([4, 2, 1, 0], )])
fn("is-happy-number", "Happy Number", U, "medium", "Seen sets", "Write `is_happy(n)`. Replace n by the sum of the squares of its digits, repeatedly. A happy number reaches 1. Others loop forever, which you can spot by remembering values already seen.", "def is_happy(n):\n    seen = set()\n    while n != 1 and n not in seen:\n        seen.add(n)\n        n = sum(int(d) ** 2 for d in str(n))\n    return n == 1", [(19, True), (2, False)], [(1, ), (7, ), (20, )])
fn("longest-without-repeat-values", "Longest Stretch of Different Values", U, "medium", "Seen sets", "Write `longest_distinct(items)` returning the length of the longest stretch with no repeated value.", "def longest_distinct(items):\n    last = {}\n    start = best = 0\n    for i, item in enumerate(items):\n        if item in last and last[item] >= start:\n            start = last[item] + 1\n        last[item] = i\n        best = max(best, i - start + 1)\n    return best", [([1, 2, 1, 3, 4], 4), ([], 0)], [([1, 1], ), ([1, 2, 3], )])
fn("count-each-value", "Count Each Value", U, "easy", "Frequency maps", "Write `tally(items)` returning a dictionary from each string to how many times it appears, without `collections.Counter`.", "def tally(items):\n    counts = {}\n    for item in items:\n        counts[item] = counts.get(item, 0) + 1\n    return counts", [(["a", "b", "a"], {"a": 2, "b": 1}), ([], {})], [(["x"], ), (["q", "q", "q"], )])
fn("most-frequent-value", "Most Frequent Value", U, "easy", "Frequency maps", "Write `mode(nums)` returning the most frequent value in a non-empty list. On a tie, return the smallest.", "def mode(nums):\n    counts = {}\n    for n in nums:\n        counts[n] = counts.get(n, 0) + 1\n    return min(counts, key=lambda k: (-counts[k], k))", [([1, 2, 2, 3], 2), ([4, 5], 4)], [([7], ), ([3, 3, 1, 1], )])
fn("appears-once-only", "Values Appearing Once", U, "easy", "Frequency maps", "Write `singles(nums)` returning the values that appear exactly once, in their original order.", "def singles(nums):\n    counts = {}\n    for n in nums:\n        counts[n] = counts.get(n, 0) + 1\n    return [n for n in nums if counts[n] == 1]", [([1, 2, 1, 3], [2, 3]), ([], [])], [([5, 5], ), ([9], )])
fn("valid-anagram-counts", "Same Letter Counts", U, "easy", "Frequency maps", "Write `same_letters(a, b)` returning True if both have the same letters with the same counts, using dictionaries rather than sorting.", "def same_letters(a, b):\n    if len(a) != len(b):\n        return False\n    counts = {}\n    for ch in a:\n        counts[ch] = counts.get(ch, 0) + 1\n    for ch in b:\n        if counts.get(ch, 0) == 0:\n            return False\n        counts[ch] -= 1\n    return True", [(("listen", "silent"), True), (("aab", "abb"), False)], [("", ""), ("a", "b"), ("abc", "ab")])
fn("can-build-from-letters", "Build a Note From Letters", U, "easy", "Frequency maps", "Write `can_build(note, letters)` returning True if `note` can be made using each character in `letters` at most once.", "def can_build(note, letters):\n    counts = {}\n    for ch in letters:\n        counts[ch] = counts.get(ch, 0) + 1\n    for ch in note:\n        if counts.get(ch, 0) == 0:\n            return False\n        counts[ch] -= 1\n    return True", [(("aa", "aab"), True), (("aa", "ab"), False)], [("", ""), ("a", ""), ("abc", "cba")])
fn("top-k-frequent-values", "Most Frequent K Values", U, "medium", "Frequency maps", "Write `top_k(nums, k)` returning the k most frequent values, most frequent first, and smaller values first on a tie.", "def top_k(nums, k):\n    counts = {}\n    for n in nums:\n        counts[n] = counts.get(n, 0) + 1\n    return sorted(counts, key=lambda v: (-counts[v], v))[:k]", [(([1, 1, 1, 2, 2, 3], 2), [1, 2]), (([1], 1), [1])], [([], 1), ([4, 4, 5, 5], 1), ([1, 2, 3], 5)])
fn("majority-value-check", "Majority Value", U, "medium", "Frequency maps", "Write `majority(nums)` returning the value appearing in more than half the positions, or None.", "def majority(nums):\n    counts = {}\n    for n in nums:\n        counts[n] = counts.get(n, 0) + 1\n        if counts[n] * 2 > len(nums):\n            return n\n    return None", [([3, 3, 4], 3), ([1, 2], None)], [([], ), ([5], ), ([2, 2, 1, 1, 2], )])
fn("pair-indices-with-difference", "Pair With a Given Difference", U, "medium", "Complement lookup", "Write `has_difference(nums, k)` returning True if two different positions hold values that differ by exactly k, where k >= 0.", "def has_difference(nums, k):\n    seen = set()\n    for n in nums:\n        if n - k in seen or n + k in seen:\n            return True\n        seen.add(n)\n    return False", [(([1, 5, 3], 2), True), (([1, 2], 9), False)], [([], 0), ([1], 0), ([1, 1], 0)])
fn("count-pairs-with-sum-fast", "Count Pairs With a Sum, Fast", U, "medium", "Complement lookup", "Write `pair_count(nums, target)` counting pairs of positions i < j adding up to `target`, in one pass. For each value, look up how many complements came before it.", "def pair_count(nums, target):\n    seen = {}\n    count = 0\n    for n in nums:\n        count += seen.get(target - n, 0)\n        seen[n] = seen.get(n, 0) + 1\n    return count", [(([1, 2, 3, 4], 5), 2), (([1, 1, 1], 2), 3)], [([], 0), ([5], 10), ([2, 2, 2, 2], 4)])
fn("two-lists-sum-pair", "Pair Across Two Lists", U, "medium", "Complement lookup", "Write `cross_pair(a, b, target)` returning True if a value from `a` and a value from `b` add up to `target`.", "def cross_pair(a, b, target):\n    wanted = set(b)\n    return any(target - x in wanted for x in a)", [(([1, 2], [3, 4], 6), True), (([1], [1], 5), False)], [([], [1], 1), ([0], [0], 0)])
fn("longest-zero-sum-stretch", "Longest Stretch Totalling Zero", U, "hard", "Complement lookup", "Write `longest_zero(nums)` returning the length of the longest stretch adding up to 0. If the running total repeats, the items between total 0.", "def longest_zero(nums):\n    first = {0: -1}\n    total = best = 0\n    for i, n in enumerate(nums):\n        total += n\n        if total in first:\n            best = max(best, i - first[total])\n        else:\n            first[total] = i\n    return best", [([1, -1, 3, 2, -2], 2), ([1, 2], 0)], [([], ), ([0], ), ([1, 2, -3], ), ([3, -3, 3, -3], )])
fn("group-numbers-by-digit-sum", "Group by Digit Sum", U, "medium", "Grouping by key", "Write `by_digit_sum(nums)` returning a dictionary from a digit sum, as text, to the list of numbers with that digit sum, in original order.", "def by_digit_sum(nums):\n    groups = {}\n    for n in nums:\n        key = str(sum(int(d) for d in str(n)))\n        groups.setdefault(key, []).append(n)\n    return groups", [([12, 3, 30], {"3": [12, 3, 30]}), ([], {})], [([1, 2, 10], ), ([99], )])
fn("isomorphic-strings", "Same Letter Pattern", U, "medium", "Grouping by key", "Write `same_pattern(a, b)`. They match if each letter of `a` maps to one letter of `b` consistently, and no two letters map to the same one.", "def same_pattern(a, b):\n    if len(a) != len(b):\n        return False\n    forward, backward = {}, {}\n    for x, y in zip(a, b):\n        if forward.get(x, y) != y or backward.get(y, x) != x:\n            return False\n        forward[x], backward[y] = y, x\n    return True", [(("egg", "add"), True), (("foo", "bar"), False)], [("", ""), ("ab", "aa"), ("paper", "title"), ("a", "ab")])
fn("word-pattern-match", "Words Follow a Pattern", U, "medium", "Grouping by key", "Write `follows(pattern, sentence)`. Each pattern letter stands for one word and each word for one letter, as in `abba` and `dog cat cat dog`.", "def follows(pattern, sentence):\n    words = sentence.split()\n    if len(words) != len(pattern):\n        return False\n    forward, backward = {}, {}\n    for letter, word in zip(pattern, words):\n        if forward.get(letter, word) != word or backward.get(word, letter) != letter:\n            return False\n        forward[letter], backward[word] = word, letter\n    return True", [(("abba", "dog cat cat dog"), True), (("abba", "dog dog dog dog"), False)], [("a", ""), ("ab", "x y"), ("aaa", "x x x")])

U = "stacks-queues"
fn("reverse-with-a-stack", "Reverse With a Stack", U, "easy", "Stack basics", "Write `reverse_stack(items)` pushing every item onto a stack, then popping them into a new list.", "def reverse_stack(items):\n    stack = []\n    for item in items:\n        stack.append(item)\n    out = []\n    while stack:\n        out.append(stack.pop())\n    return out", [([1, 2, 3], [3, 2, 1]), ([], [])], [(["a"], )])
fn("backspace-text", "Typing With Backspace", U, "easy", "Stack basics", "Write `typed(text)` where `#` means backspace. Return the final text. Backspace on empty text does nothing.", 'def typed(text):\n    stack = []\n    for ch in text:\n        if ch == "#":\n            if stack:\n                stack.pop()\n        else:\n            stack.append(ch)\n    return "".join(stack)', [("ab#c", "ac"), ("##", "")], [("", ), ("a##b", ), ("abc", )])
fn("remove-adjacent-duplicates", "Remove Touching Duplicates", U, "easy", "Stack basics", "Write `squash(text)` removing pairs of equal neighbouring letters, repeatedly, until none remain.", 'def squash(text):\n    stack = []\n    for ch in text:\n        if stack and stack[-1] == ch:\n            stack.pop()\n        else:\n            stack.append(ch)\n    return "".join(stack)', [("abbaca", "ca"), ("aa", "")], [("", ), ("abc", ), ("azxxzy", )])
fn("min-stack-operations", "Stack With Minimum", U, "medium", "Design with stacks and queues", "Write `min_after(ops)`, where each operation is `[\"push\", x]`, `[\"pop\"]` or `[\"min\"]`. Return the results of each `min`, in order. Keep a second stack of the smallest value so far, so each `min` takes one step. Operations are always valid.", 'def min_after(ops):\n    stack, lows, out = [], [], []\n    for op in ops:\n        if op[0] == "push":\n            stack.append(op[1])\n            lows.append(min(op[1], lows[-1]) if lows else op[1])\n        elif op[0] == "pop":\n            stack.pop()\n            lows.pop()\n        else:\n            out.append(lows[-1])\n    return out', [([["push", 3], ["push", 1], ["min"], ["pop"], ["min"]], [1, 3]), ([], [])], [([["push", 5], ["min"]], ), ([["push", 2], ["push", 2], ["pop"], ["min"]], )])
fn("simplify-file-path", "Simplify a File Path", U, "medium", "Matching and parsing", "Write `simplify(path)` for a Unix-style absolute path. `.` means here, `..` means up one, and extra slashes do not matter. Return the shortest equivalent path.", 'def simplify(path):\n    stack = []\n    for part in path.split("/"):\n        if part == "..":\n            if stack:\n                stack.pop()\n        elif part and part != ".":\n            stack.append(part)\n    return "/" + "/".join(stack)', [("/a/./b/../c/", "/a/c"), ("/../", "/")], [("/", ), ("//x//y", ), ("/a/b/c/../..", )])
fn("longest-balanced-brackets", "Longest Balanced Brackets", U, "hard", "Matching and parsing", "Write `longest_balanced(text)` for text of `(` and `)`. Return the length of the longest balanced stretch. Keep a stack of positions.", 'def longest_balanced(text):\n    stack = [-1]\n    best = 0\n    for i, ch in enumerate(text):\n        if ch == "(":\n            stack.append(i)\n        else:\n            stack.pop()\n            if stack:\n                best = max(best, i - stack[-1])\n            else:\n                stack.append(i)\n    return best', [("(()", 2), (")()())", 4)], [("", ), ("((", ), ("()()", ), ("(()())", )])
fn("decode-repeat-string", "Decode Repeated Text", U, "hard", "Matching and parsing", "Write `decode(text)`. `k[abc]` means abc repeated k times, and these can be nested, so `2[a3[b]]` becomes `abbbabbb`.", 'def decode(text):\n    stack = []\n    current, number = "", 0\n    for ch in text:\n        if ch.isdigit():\n            number = number * 10 + int(ch)\n        elif ch == "[":\n            stack.append((current, number))\n            current, number = "", 0\n        elif ch == "]":\n            before, times = stack.pop()\n            current = before + current * times\n        else:\n            current += ch\n    return current', [("3[a]", "aaa"), ("2[a3[b]]", "abbbabbb")], [("", ), ("abc", ), ("2[ab]c", ), ("10[x]", )])
fn("basic-calculator-plus-minus", "Calculator With Brackets", U, "hard", "Matching and parsing", "Write `calc(text)` evaluating whole numbers with `+`, `-`, brackets and spaces. Use a stack to remember the total and sign outside each bracket.", 'def calc(text):\n    total, number, sign = 0, 0, 1\n    stack = []\n    for ch in text:\n        if ch.isdigit():\n            number = number * 10 + int(ch)\n        elif ch in "+-":\n            total += sign * number\n            number = 0\n            sign = 1 if ch == "+" else -1\n        elif ch == "(":\n            stack.append((total, sign))\n            total, sign = 0, 1\n        elif ch == ")":\n            total += sign * number\n            number = 0\n            before, outer = stack.pop()\n            total = before + outer * total\n    return total + sign * number', [("1 + 2 - 3", 0), ("(1+(4+5+2)-3)+(6+8)", 23)], [("5", ), ("2-(1-1)", ), ("10 - (2 + 3)", )])
fn("next-greater-value", "Next Greater Value", U, "medium", "Monotonic stack", "Write `next_greater(nums)` returning, for each position, the next value to its right that is larger, or -1. A stack of positions still waiting does this in one pass.", "def next_greater(nums):\n    out = [-1] * len(nums)\n    stack = []\n    for i, n in enumerate(nums):\n        while stack and nums[stack[-1]] < n:\n            out[stack.pop()] = n\n        stack.append(i)\n    return out", [([2, 1, 3], [3, 3, -1]), ([3, 2, 1], [-1, -1, -1])], [([], ), ([1], ), ([1, 1], ), ([1, 3, 2, 4], )])
fn("largest-rectangle-bars", "Largest Rectangle in Bars", U, "hard", "Monotonic stack", "Write `largest_rect(heights)` returning the largest rectangle area in a bar chart with bars of width 1.", "def largest_rect(heights):\n    stack = []\n    best = 0\n    for i, h in enumerate(heights + [0]):\n        start = i\n        while stack and stack[-1][1] > h:\n            j, tall = stack.pop()\n            best = max(best, tall * (i - j))\n            start = j\n        stack.append((start, h))\n    return best", [([2, 1, 5, 6, 2, 3], 10), ([2, 4], 4)], [([], ), ([1], ), ([1, 1, 1], ), ([5, 4, 3], )])
fn("remove-to-make-smallest", "Remove Digits to Make Smallest", U, "hard", "Monotonic stack", "Write `smallest_after(digits, k)` for text of digits. Remove k digits to make the smallest number, and return it as text with no leading zeros, or `\"0\"` if nothing is left.", 'def smallest_after(digits, k):\n    stack = []\n    for d in digits:\n        while k and stack and stack[-1] > d:\n            stack.pop()\n            k -= 1\n        stack.append(d)\n    if k:\n        stack = stack[:-k]\n    return "".join(stack).lstrip("0") or "0"', [(("1432219", 3), "1219"), (("10", 2), "0")], [("10200", 1), ("9", 1), ("12345", 2)])
fn("queue-simulation-order", "Serve a Queue", U, "easy", "Queue and deque", "Write `served(ops)` where each operation is a name to join the queue, or `\"next\"` to serve the person in front. Return the names in the order served. `next` on an empty queue does nothing. Use `collections.deque`.", 'from collections import deque\n\ndef served(ops):\n    queue = deque()\n    out = []\n    for op in ops:\n        if op == "next":\n            if queue:\n                out.append(queue.popleft())\n        else:\n            queue.append(op)\n    return out', [(["a", "b", "next", "next"], ["a", "b"]), (["next"], [])], [([], ), (["a", "next", "b"], )])
fn("sliding-window-maximum", "Window Maximums", U, "hard", "Queue and deque", "Write `window_max(nums, k)` returning the largest value in each window of k neighbours. A deque of positions, with values decreasing, gives each answer in about one step.", "from collections import deque\n\ndef window_max(nums, k):\n    window = deque()\n    out = []\n    for i, n in enumerate(nums):\n        while window and nums[window[-1]] <= n:\n            window.pop()\n        window.append(i)\n        if window[0] <= i - k:\n            window.popleft()\n        if i >= k - 1:\n            out.append(nums[window[0]])\n    return out", [(([1, 3, -1, -3, 5, 3], 3), [3, 3, 5, 5]), (([1], 1), [1])], [([9, 8, 7], 2), ([1, 2, 3], 1), ([4, 4], 2)])
fn("round-robin-last", "Last One Standing", U, "medium", "Queue and deque", "People 1 to n stand in a circle. Going round, every k-th person leaves. Write `last_standing(n, k)` returning who remains, using a queue.", "from collections import deque\n\ndef last_standing(n, k):\n    queue = deque(range(1, n + 1))\n    while len(queue) > 1:\n        queue.rotate(-(k - 1))\n        queue.popleft()\n    return queue[0]", [((5, 2), 3), ((1, 3), 1)], [(6, 1), (7, 3), (2, 2)])
fn("palindrome-with-deque", "Palindrome With a Deque", U, "easy", "Queue and deque", "Write `deque_palindrome(text)` removing a letter from each end and comparing until at most one is left.", "from collections import deque\n\ndef deque_palindrome(text):\n    letters = deque(text)\n    while len(letters) > 1:\n        if letters.popleft() != letters.pop():\n            return False\n    return True", [("level", True), ("ab", False)], [("", ), ("a", ), ("abba", )])
fn("stack-from-a-queue", "Stack Built From a Queue", U, "medium", "Design with stacks and queues", "Write `stack_results(ops)` with operations `[\"push\", x]` and `[\"pop\"]`, implementing the stack using one `deque` as a queue only: join at the back and leave from the front. Return what each pop gives, or None when empty.", 'from collections import deque\n\ndef stack_results(ops):\n    queue = deque()\n    out = []\n    for op in ops:\n        if op[0] == "push":\n            queue.append(op[1])\n            for _ in range(len(queue) - 1):\n                queue.append(queue.popleft())\n        else:\n            out.append(queue.popleft() if queue else None)\n    return out', [([["push", 1], ["push", 2], ["pop"]], [2]), ([["pop"]], [None])], [([], ), ([["push", 1], ["pop"], ["pop"]], )])
fn("browser-history-steps", "Browser History", U, "medium", "Design with stacks and queues", "Write `browse(start, ops)`, where each operation is `[\"visit\", url]`, `[\"back\"]` or `[\"forward\"]`. Return the current page after them all. Visiting clears forward history, and going back or forward past the end stays put.", 'def browse(start, ops):\n    back, forward = [start], []\n    for op in ops:\n        if op[0] == "visit":\n            back.append(op[1])\n            forward.clear()\n        elif op[0] == "back" and len(back) > 1:\n            forward.append(back.pop())\n        elif op[0] == "forward" and forward:\n            back.append(forward.pop())\n    return back[-1]', [(("a", [["visit", "b"], ["back"]]), "a"), (("a", [["back"]]), "a")], [("h", [["visit", "x"], ["back"], ["forward"]]), ("h", [["visit", "x"], ["back"], ["visit", "y"], ["forward"]]), ("h", [])])

U = "linked-lists"
linked("linked-list-length", "Length of a Linked List", U, "easy", "Traversal", "Write `length(head)` counting the nodes.", "def length(head):\n    count = 0\n    while head:\n        count += 1\n        head = head.next\n    return count", "length(build_list({0}))", [([1, 2, 3], 3), ([], 0)], [([9], )])
linked("linked-list-sum", "Total of a Linked List", U, "easy", "Traversal", "Write `total(head)` adding up the values.", "def total(head):\n    result = 0\n    while head:\n        result += head.val\n        head = head.next\n    return result", "total(build_list({0}))", [([1, 2, 3], 6), ([], 0)], [([-1, 1], )])
linked("linked-list-contains", "Is the Value Present", U, "easy", "Traversal", "Write `contains(head, x)` returning True if any node holds `x`.", "def contains(head, x):\n    while head:\n        if head.val == x:\n            return True\n        head = head.next\n    return False", "contains(build_list({0}), {1})", [(([1, 2], 2), True), (([], 1), False)], [([3], 4)])
linked("linked-list-kth-from-end", "Kth From the End", U, "medium", "Fast and slow pointers", "Write `kth_from_end(head, k)` returning the value k nodes from the end, where k = 1 is the last, in one pass. Move one pointer k steps ahead first. k is always valid.", "def kth_from_end(head, k):\n    lead = head\n    for _ in range(k):\n        lead = lead.next\n    trail = head\n    while lead:\n        lead, trail = lead.next, trail.next\n    return trail.val", "kth_from_end(build_list({0}), {1})", [(([1, 2, 3], 1), 3), (([1, 2, 3], 3), 1)], [([5], 1), ([1, 2, 3, 4], 2)])
linked("delete-all-of-value", "Delete a Value", U, "easy", "Merging and dummy heads", "Write `delete_value(head, x)` removing every node holding `x`, and returning the new head. A placeholder node in front makes removing the first node simple.", "def delete_value(head, x):\n    dummy = ListNode(0, head)\n    node = dummy\n    while node.next:\n        if node.next.val == x:\n            node.next = node.next.next\n        else:\n            node = node.next\n    return dummy.next", "to_list(delete_value(build_list({0}), {1}))", [(([1, 2, 1], 1), [2]), (([], 1), [])], [([1, 1], 1), ([2, 3], 9)])
linked("remove-kth-from-end", "Remove Kth From the End", U, "medium", "Merging and dummy heads", "Write `remove_kth(head, k)` removing the k-th node from the end, where k = 1 is the last, and returning the new head.", "def remove_kth(head, k):\n    dummy = ListNode(0, head)\n    lead = trail = dummy\n    for _ in range(k):\n        lead = lead.next\n    while lead.next:\n        lead, trail = lead.next, trail.next\n    trail.next = trail.next.next\n    return dummy.next", "to_list(remove_kth(build_list({0}), {1}))", [(([1, 2, 3], 1), [1, 2]), (([1], 1), [])], [([1, 2], 2), ([1, 2, 3, 4, 5], 2)])
linked("dedupe-sorted-linked-list", "Remove Repeats From a Sorted List", U, "easy", "Pointer rewiring", "Write `dedupe(head)` for a sorted linked list, keeping one of each value.", "def dedupe(head):\n    node = head\n    while node and node.next:\n        if node.val == node.next.val:\n            node.next = node.next.next\n        else:\n            node = node.next\n    return head", "to_list(dedupe(build_list({0})))", [([1, 1, 2], [1, 2]), ([], [])], [([1, 1, 1], ), ([1, 2, 3], )])
linked("swap-adjacent-nodes", "Swap Neighbouring Nodes", U, "medium", "Pointer rewiring", "Write `swap_pairs(head)` swapping each pair of neighbours by changing links, not values.", "def swap_pairs(head):\n    dummy = ListNode(0, head)\n    node = dummy\n    while node.next and node.next.next:\n        a, b = node.next, node.next.next\n        a.next, b.next, node.next = b.next, a, b\n        node = a\n    return dummy.next", "to_list(swap_pairs(build_list({0})))", [([1, 2, 3, 4], [2, 1, 4, 3]), ([], [])], [([1], ), ([1, 2, 3], )])
linked("reverse-part-of-list", "Reverse Part of a List", U, "hard", "Pointer rewiring", "Write `reverse_between(head, left, right)` reversing positions `left` to `right`, counted from 1, and returning the head.", "def reverse_between(head, left, right):\n    dummy = ListNode(0, head)\n    before = dummy\n    for _ in range(left - 1):\n        before = before.next\n    current = before.next\n    for _ in range(right - left):\n        moved = current.next\n        current.next = moved.next\n        moved.next = before.next\n        before.next = moved\n    return dummy.next", "to_list(reverse_between(build_list({0}), {1}, {2}))", [(([1, 2, 3, 4, 5], 2, 4), [1, 4, 3, 2, 5]), (([1], 1, 1), [1])], [([1, 2], 1, 2), ([1, 2, 3], 2, 3)])
linked("rotate-linked-list", "Rotate a Linked List", U, "medium", "Pointer rewiring", "Write `rotate_right(head, k)` moving the list right by k places, with nodes wrapping around.", "def rotate_right(head, k):\n    if not head:\n        return None\n    size, tail = 1, head\n    while tail.next:\n        tail = tail.next\n        size += 1\n    k %= size\n    if k == 0:\n        return head\n    node = head\n    for _ in range(size - k - 1):\n        node = node.next\n    new_head = node.next\n    node.next = None\n    tail.next = head\n    return new_head", "to_list(rotate_right(build_list({0}), {1}))", [(([1, 2, 3], 1), [3, 1, 2]), (([], 2), [])], [([1, 2], 2), ([1, 2, 3], 4), ([1], 9)])
linked("linked-list-palindrome", "Is the List a Palindrome", U, "medium", "Fast and slow pointers", "Write `is_palindrome_list(head)`. Try finding the middle with fast and slow pointers, then reversing the second half.", "def is_palindrome_list(head):\n    slow = fast = head\n    while fast and fast.next:\n        slow, fast = slow.next, fast.next.next\n    prev = None\n    while slow:\n        slow.next, prev, slow = prev, slow, slow.next\n    while prev:\n        if prev.val != head.val:\n            return False\n        prev, head = prev.next, head.next\n    return True", "is_palindrome_list(build_list({0}))", [([1, 2, 1], True), ([1, 2], False)], [([], ), ([1], ), ([1, 2, 2, 1], )])
linked("odd-positions-first", "Odd Positions First", U, "medium", "Pointer rewiring", "Write `odd_even(head)` moving all nodes at odd positions (1, 3, 5...) before those at even positions, keeping each group's order.", "def odd_even(head):\n    if not head:\n        return None\n    odd, even, even_head = head, head.next, head.next\n    while even and even.next:\n        odd.next = even.next\n        odd = odd.next\n        even.next = odd.next\n        even = even.next\n    odd.next = even_head\n    return head", "to_list(odd_even(build_list({0})))", [([1, 2, 3, 4, 5], [1, 3, 5, 2, 4]), ([], [])], [([1], ), ([1, 2], )])
linked("partition-around-value", "Partition a List", U, "medium", "Merging and dummy heads", "Write `partition(head, x)` moving all values below `x` before the others, keeping each group's order. Build two lists, each with a placeholder at the front, then join them.", "def partition(head, x):\n    low_head = low = ListNode()\n    high_head = high = ListNode()\n    while head:\n        if head.val < x:\n            low.next = head\n            low = low.next\n        else:\n            high.next = head\n            high = high.next\n        head = head.next\n    high.next = None\n    low.next = high_head.next\n    return low_head.next", "to_list(partition(build_list({0}), {1}))", [(([1, 4, 3, 2], 3), [1, 2, 4, 3]), (([], 1), [])], [([5], 1), ([1], 5), ([3, 3], 3)])
linked("add-numbers-as-lists", "Add Two Numbers Stored as Lists", U, "medium", "Merging and dummy heads", "Each list stores a number's digits, smallest place first, so 3 -> 2 means 23. Write `add_lists(a, b)` returning their sum in the same form.", "def add_lists(a, b):\n    dummy = node = ListNode()\n    carry = 0\n    while a or b or carry:\n        total = carry + (a.val if a else 0) + (b.val if b else 0)\n        carry, digit = divmod(total, 10)\n        node.next = ListNode(digit)\n        node = node.next\n        a = a.next if a else None\n        b = b.next if b else None\n    return dummy.next", "to_list(add_lists(build_list({0}), build_list({1})))", [(([3, 2], [5]), [8, 2]), (([9, 9], [1]), [0, 0, 1])], [([], []), ([0], [0]), ([1], [9, 9, 9])])
linked("reorder-ends-alternating", "Alternate From Both Ends", U, "hard", "Fast and slow pointers", "Write `reorder(head)` rearranging a list to first, last, second, second-last, and so on, by changing links. Return the head.", "def reorder(head):\n    if not head or not head.next:\n        return head\n    slow = fast = head\n    while fast.next and fast.next.next:\n        slow, fast = slow.next, fast.next.next\n    second, slow.next = slow.next, None\n    prev = None\n    while second:\n        second.next, prev, second = prev, second, second.next\n    first, second = head, prev\n    while second:\n        first_next, second_next = first.next, second.next\n        first.next, second.next = second, first_next\n        first, second = first_next, second_next\n    return head", "to_list(reorder(build_list({0})))", [([1, 2, 3, 4], [1, 4, 2, 3]), ([], [])], [([1], ), ([1, 2], ), ([1, 2, 3, 4, 5], )])
